import java.util.Arrays;

public class ArraysUtilDemo {
    public static void main(String[] args) {
        int[] scores = {45, 12, 85, 32, 8};

        // 1. Pretty Printing with Arrays.toString()
        System.out.println("Original: " + Arrays.toString(scores));

        // 2. In-place sorting
        Arrays.sort(scores);
        System.out.println("Sorted:   " + Arrays.toString(scores));

        // 3. Binary Search on sorted array
        int idx = Arrays.binarySearch(scores, 32);
        System.out.println("Value 32 found at index: " + idx);

        // 4. Bulk Filling
        int[] buffer = new int[4];
        Arrays.fill(buffer, -1);
        System.out.println("Filled Buffer: " + Arrays.toString(buffer));
    }
}

